begin;
alter table public.messages add column if not exists onboarding_user_id uuid references auth.users(id) on delete cascade;
alter table public.documents add column if not exists onboarding_user_id uuid references auth.users(id) on delete cascade;
alter table public.project_photos add column if not exists onboarding_user_id uuid references auth.users(id) on delete cascade;
create index if not exists messages_onboarding_user_idx on public.messages(onboarding_user_id,created_at desc) where onboarding_user_id is not null;
create index if not exists documents_onboarding_user_idx on public.documents(onboarding_user_id,created_at desc) where onboarding_user_id is not null;
create index if not exists photos_onboarding_user_idx on public.project_photos(onboarding_user_id,created_at desc) where onboarding_user_id is not null;
drop policy if exists planning_messages_customer_read on public.messages;
create policy planning_messages_customer_read on public.messages for select to authenticated using (onboarding_user_id=auth.uid());
drop policy if exists planning_messages_customer_insert on public.messages;
create policy planning_messages_customer_insert on public.messages for insert to authenticated with check (project_id is null and onboarding_user_id=auth.uid() and sender_id=auth.uid() and sender_role='client');
drop policy if exists planning_documents_customer_read on public.documents;
create policy planning_documents_customer_read on public.documents for select to authenticated using (onboarding_user_id=auth.uid());
drop policy if exists planning_documents_customer_insert on public.documents;
create policy planning_documents_customer_insert on public.documents for insert to authenticated with check (project_id is null and onboarding_user_id=auth.uid() and uploaded_by=auth.uid() and uploaded_role='client');
drop policy if exists planning_photos_customer_read on public.project_photos;
create policy planning_photos_customer_read on public.project_photos for select to authenticated using (onboarding_user_id=auth.uid());
drop policy if exists planning_photos_customer_insert on public.project_photos;
create policy planning_photos_customer_insert on public.project_photos for insert to authenticated with check (project_id is null and onboarding_user_id=auth.uid() and uploaded_by=auth.uid() and uploaded_role='client');
drop policy if exists storage_planning_customer_insert on storage.objects;
create policy storage_planning_customer_insert on storage.objects for insert to authenticated with check (bucket_id in ('project-files','project-photos') and (storage.foldername(name))[1]::uuid=auth.uid() and (storage.foldername(name))[2]='customer' and (storage.foldername(name))[3]::uuid=auth.uid());
drop policy if exists storage_planning_read on storage.objects;
create policy storage_planning_read on storage.objects for select to authenticated using (bucket_id in ('project-files','project-photos') and ((storage.foldername(name))[1]::uuid=auth.uid() or public.admin_has_permission('content') or public.admin_has_permission('customers')));
commit;
